function BrakesCoachScreen({ vehicle, scenario }) {
  const [i, setI] = useState(0);
  const step = applyVariants(scenario.steps[i], vehicle);
  const preferShop = matchAdaptiveRules(scenario.adaptive_rules, vehicle).some(r => r.prefer_shop);

  useEffect(() => emitFocus({ part: 'brakes', action: step.id }), [step.id]);

  return (
    <CoachShell
      media={resolveAsset(scenario, step)}
      title={step.title}
      body={step.description}
      safety={step.safety_warning}
      banner={preferShop && step.id === 'diy_or_shop' ? 'EPB / sensors detected — shop is OK' : null}
      actions={step.action_buttons}
      onAction={(btn) => handleCoachAction(btn, { setI, scenario })}
    />
  );
}
